    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum ItemStatus {\n  DRAFT\n  SAVED\n}\n\nenum Role {\n  USER\n  ASSISTANT\n  SYSTEM\n}\n\nmodel User {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  passwordHash String\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  profile                 UserProfile?\n  stylePreferences        StylePreferences?\n  wardrobeItems           WardrobeItem[]\n  outfits                 Outfit[]\n  conversations           Conversation[]\n  shoppingRecommendations ShoppingRecommendation[]\n}\n\nmodel UserProfile {\n  id          String   @id @default(cuid())\n  userId      String   @unique\n  displayName String?\n  avatarUrl   String?\n  bio         String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel StylePreferences {\n  id                  String   @id @default(cuid())\n  userId              String   @unique\n  styleGoals          Json?\n  styleTags           Json?\n  colorPalette        Json?\n  preferredCategories Json?\n  budgetMin           Int?\n  budgetMax           Int?\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel WardrobeItem {\n  id              String     @id @default(cuid())\n  userId          String\n  imageUrl        String\n  category        String\n  subcategory     String?\n  color           String?\n  secondaryColors Json?\n  pattern         String?\n  material        String?\n  fit             String?\n  styleTags       Json?\n  formality       String?\n  season          String?\n  brand           String?\n  purchaseDate    DateTime?\n  price           Decimal?   @db.Decimal(10, 2)\n  favorite        Boolean    @default(false)\n  wearCount       Int        @default(0)\n  notes           String?\n  status          ItemStatus @default(DRAFT)\n  source          String     @default(\"ai\")\n  createdAt       DateTime   @default(now())\n  updatedAt       DateTime   @updatedAt\n\n  user        User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  outfitItems OutfitItem[]\n}\n\nmodel Outfit {\n  id         String   @id @default(cuid())\n  userId     String\n  title      String\n  occasion   String?\n  notes      String?\n  isFavorite Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  user        User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  outfitItems OutfitItem[]\n}\n\nmodel OutfitItem {\n  id             String @id @default(cuid())\n  outfitId       String\n  wardrobeItemId String\n  position       Int    @default(0)\n\n  outfit       Outfit       @relation(fields: [outfitId], references: [id], onDelete: Cascade)\n  wardrobeItem WardrobeItem @relation(fields: [wardrobeItemId], references: [id], onDelete: Cascade)\n\n  @@unique([outfitId, wardrobeItemId])\n}\n\nmodel Conversation {\n  id        String   @id @default(cuid())\n  userId    String\n  title     String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user     User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  messages Message[]\n}\n\nmodel Message {\n  id             String   @id @default(cuid())\n  conversationId String\n  role           Role\n  content        Json\n  createdAt      DateTime @default(now())\n\n  conversation Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n}\n\nmodel ShoppingRecommendation {\n  id          String   @id @default(cuid())\n  userId      String\n  category    String?\n  title       String\n  description String?\n  reason      String?\n  productUrl  String?\n  imageUrl    String?\n  price       Decimal? @db.Decimal(10, 2)\n  source      String?\n  createdAt   DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel CharacterProfile {\n  id          String   @id @default(cuid())\n  name        String\n  personality Json?\n  greeting    String?\n  avatarUrl   String?\n  isDefault   Boolean  @default(false)\n  createdAt   DateTime @default(now())\n}\n",
